// Package helpers tests — T-17 (Phase 1): the Python-semantics helper
// library for doc 05 §3 items 2/3/4/6/7/12/13/16.
//
// THE LAW: the goldens were GENERATED by running the pinned reference
// interpreter's own semantics (the helpers port Python BUILTINS —
// str[:n], str.rstrip(chars), round(x, n), dict.fromkeys,
// os.path.normcase, f"{n:,}", str.lower, str()) via
// testdiff/goldens/dump_helpers.py — never hand-typed. Regenerate with:
//
//	python3 testdiff/goldens/dump_helpers.py
//
// Table-test acceptance (task list): U+0130, U+2026, 🗑️ bytes all
// present in the corpora. Full batteries for the PROMOTED helpers
// (splitlines, strip whitespace, pyRepr) stay pinned in their original
// homes' goldens (taxonomy, prompts) — this corpus carries slim sets.
package helpers

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

func goldenBytes(t *testing.T, name string) []byte {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read golden %s (generate with testdiff/goldens/dump_helpers.py): %v", name, err)
	}
	return raw
}

func loadCorpus(t *testing.T) map[string]any {
	t.Helper()
	dec := json.NewDecoder(bytes.NewReader(goldenBytes(t, "helpers_corpus.golden.json")))
	dec.UseNumber()
	var doc map[string]any
	if err := dec.Decode(&doc); err != nil {
		t.Fatalf("decode corpus: %v", err)
	}
	return doc
}

func section(t *testing.T, doc map[string]any, key string) []any {
	t.Helper()
	v, ok := doc[key].([]any)
	if !ok {
		t.Fatalf("corpus section %q missing", key)
	}
	return v
}

func str(t *testing.T, v any) string {
	t.Helper()
	s, ok := v.(string)
	if !ok {
		t.Fatalf("corpus string wrong type: %T", v)
	}
	return s
}

// TestGoldenCutRunes pins code-point slicing (doc 05 §3 item 3): the
// first n CODE POINTS — 🗑️+VS16 is two code points, U+0130 one, CJK one
// each; byte-slicing would cut mid-rune.
func TestGoldenCutRunes(t *testing.T) {
	doc := loadCorpus(t)
	for _, e := range section(t, doc, "cut_runes") {
		p := e.([]any)
		n64, nerr := p[1].(json.Number).Int64()
		if nerr != nil {
			t.Fatalf("corpus cut n: %v", nerr)
		}
		s, n, want := str(t, p[0]), int(n64), str(t, p[2])
		if got := CutRunes(s, n); got != want {
			t.Errorf("CutRunes(%q, %d) = %q, want %q", s, n, got, want)
		}
	}
}

// TestGoldenStripChars pins char-SET strip semantics (doc 05 §3 items
// 6/7): any combination of the set's characters strips from the end (or
// both sides / the start) — NOT a suffix match; an EMPTY set strips
// nothing; the 🗑️ probe strips the full two-code-point sequence via the
// set; U+0130 strips as its own code point.
func TestGoldenStripChars(t *testing.T) {
	doc := loadCorpus(t)
	for _, e := range section(t, doc, "strip_chars") {
		p := e.([]any)
		s, chars := str(t, p[0]), str(t, p[1])
		if got, want := RstripChars(s, chars), str(t, p[2]); got != want {
			t.Errorf("RstripChars(%q, %q) = %q, want %q", s, chars, got, want)
		}
		if got, want := StripChars(s, chars), str(t, p[3]); got != want {
			t.Errorf("StripChars(%q, %q) = %q, want %q", s, chars, got, want)
		}
		if got, want := LstripChars(s, chars), str(t, p[4]); got != want {
			t.Errorf("LstripChars(%q, %q) = %q, want %q", s, chars, got, want)
		}
	}
}

// TestGoldenRoundHalfEven pins Python round(x, n) — banker's rounding
// evaluated on the EXACT binary value of x (big.Rat): 2.675 → 2.67 (the
// double is 2.674999…), 0.125 → 0.12 (exact half → even), 2.5 → 2,
// 3.5 → 4, -0.5 → -0.0 (the sign survives).
func TestGoldenRoundHalfEven(t *testing.T) {
	doc := loadCorpus(t)
	for _, e := range section(t, doc, "round_half_even") {
		p := e.([]any)
		x := p[0].(json.Number)
		xf, err := x.Float64()
		if err != nil {
			t.Fatalf("corpus round x %q: %v", x.String(), err)
		}
		n64, nerr := p[1].(json.Number).Int64()
		if nerr != nil {
			t.Fatalf("corpus round n: %v", nerr)
		}
		n := int(n64)
		want := p[2]
		got := RoundHalfEven(xf, n)
		// compare through the same json.Number repr the golden carries
		gotNum := json.Number(pyFloatLiteral(got))
		wantStr := want.(json.Number).String()
		if gotNum.String() != wantStr {
			t.Errorf("RoundHalfEven(%v, %d) = %s, want %s", xf, n, gotNum.String(), wantStr)
		}
	}
}

// pyFloatLiteral renders a float the way Python's json/str do —
// storage.PyFloatRepr (the exact law).
func pyFloatLiteral(f float64) string {
	return PyFloatRepr(f) // the canonical home (storage delegates here)
}

// TestGoldenOrderedDedupe pins dict.fromkeys order: first occurrence
// wins, order preserved, U+0130 ≠ i, 🗑️ dedupes against itself.
func TestGoldenOrderedDedupe(t *testing.T) {
	doc := loadCorpus(t)
	for _, e := range section(t, doc, "ordered_dedupe") {
		p := e.([]any)
		in := p[0].([]any)
		want := p[1].([]any)
		got := OrderedDedupe(in)
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Errorf("OrderedDedupe(%v) = %v, want %v", in, got, want)
		}
	}
	// the typed generic over non-any comparables
	if got := OrderedDedupe([]int{1, 2, 1, 3, 2, 1}); fmt.Sprint(got) != "[1 2 3]" {
		t.Errorf("OrderedDedupe(ints) = %v", got)
	}
	if got := OrderedDedupe([]string{"İ", "i", "İ"}); fmt.Sprint(got) != "[İ i]" {
		t.Errorf("OrderedDedupe(strings) = %v", got)
	}
}

// TestGoldenNormcase pins os.path.normcase per-platform: POSIX is the
// identity; Windows folds '/' → '\\' and applies FULL Unicode lower
// (İ → i̇, final sigma). The Go test asserts its OWN platform's column
// (matching os.path behavior exactly like the reference); the other
// column stays recorded as evidence.
func TestGoldenNormcase(t *testing.T) {
	doc := loadCorpus(t)
	posixCol, windowsCol := 1, 2
	col := posixCol
	if runtime.GOOS == "windows" {
		col = windowsCol
	}
	for _, e := range section(t, doc, "normcase") {
		p := e.([]any)
		s := str(t, p[0])
		want := str(t, p[col])
		if got := Normcase(s); got != want {
			t.Errorf("Normcase(%q) = %q, want %q (platform %s)", s, got, want, runtime.GOOS)
		}
	}
}

