// TestGoldenPyStr pins str(v) for the parity shapes: 5 → "5" but
// 5.0 → "5.0", 1e15 positional, 1e16 scientific, True/False, None →
// "None" (Python's own word — callers with special None grammar check
// nil BEFORE calling).
func TestGoldenPyStr(t *testing.T) {
	doc := loadCorpus(t)
	for _, e := range section(t, doc, "py_str") {
		p := e.([]any)
		v := p[0]
		want := str(t, p[1])
		var got string
		switch vv := v.(type) {
		case json.Number:
			got = PyStr(vv)
		case string, bool:
			got = PyStr(vv)
		case nil:
			got = PyStr(nil)
		default:
			t.Fatalf("py_str corpus wrong type: %T", v)
		}
		if got != want {
			t.Errorf("PyStr(%#v) = %q, want %q", v, got, want)
		}
	}
}

