// TestGoldenStripWS pins the slim Unicode-whitespace strip battery.
func TestGoldenStripWS(t *testing.T) {
	doc := loadCorpus(t)
	for _, e := range section(t, doc, "stripws") {
		p := e.([]any)
		s := str(t, p[0])
		ops := p[1].([]any)
		if got, want := Strip(s), str(t, ops[0]); got != want {
			t.Errorf("Strip(%q) = %q, want %q", s, got, want)
		}
		if got, want := Lstrip(s), str(t, ops[1]); got != want {
			t.Errorf("Lstrip(%q) = %q, want %q", s, got, want)
		}
		if got, want := Rstrip(s), str(t, ops[2]); got != want {
			t.Errorf("Rstrip(%q) = %q, want %q", s, got, want)
		}
	}
}

// TestRoundHalfEvenTable double-covers the acceptance's named traps with
// explicit values (the golden pins the full corpus).
func TestRoundHalfEvenTable(t *testing.T) {
	cases := []struct {
		x    float64
		n    int
		want float64
	}{
		{2.675, 2, 2.67}, {0.125, 2, 0.12}, {2.5, 0, 2}, {3.5, 0, 4},
		{0.5, 0, 0}, {-0.5, 0, math.Copysign(0, -1)},
	}
	for _, tc := range cases {
		if got := RoundHalfEven(tc.x, tc.n); got != tc.want {
			t.Errorf("RoundHalfEven(%v, %d) = %v, want %v", tc.x, tc.n, got, tc.want)
		}
	}
}

// TestFormatCommaTable double-covers the promoted function's classic
// shapes.
func TestFormatCommaTable(t *testing.T) {
	cases := []struct {
		n    int64
		want string
	}{
		{0, "0"}, {999, "999"}, {1000, "1,000"},
		{1234567, "1,234,567"}, {-1234567, "-1,234,567"},
		{math.MaxInt64, "9,223,372,036,854,775,807"},
	}
	for _, tc := range cases {
		if got := FormatComma(tc.n); got != tc.want {
			t.Errorf("FormatComma(%d) = %q, want %q", tc.n, got, tc.want)
		}
	}
}

// TestCutRunesTable double-covers the multi-byte acceptance cases.
func TestCutRunesTable(t *testing.T) {
	if got := CutRunes("🗑️ delete", 1); got != "🗑" { // U+1F5D1 alone, VS16 second
		t.Errorf("CutRunes(trash+VS16, 1) = %q, want %q", got, "🗑")
	}
	if got := CutRunes("İstanbul", 1); got != "İ" {
		t.Errorf("CutRunes(İstanbul, 1) = %q", got)
	}
	if got := CutRunes("…ellipsis", 1); got != "…" {
		t.Errorf("CutRunes(…, 1) = %q", got)
	}
}
